#!/usr/bin/env python3
import time
from AppKit import *

def find_element_by_placeholder(placeholder_text):
    """Find a UI element by its placeholder text using Accessibility APIs."""
    app = NSRunningApplication.runningApplicationsWithBundleIdentifier_("com.apple.iphonesimulator")[0]
    if not app:
        print("iPhone Simulator not found")
        return None

    window = app.accessibilityAttributeValue_(NSAccessibilityWindowsAttribute)[0]
    if not window:
        print("Window not found")
        return None

    def search_recursive(element, target_text):
        """Recursively search for element with specific placeholder."""
        if element is None:
            return None

        try:
            placeholder = element.accessibilityAttributeValue_(NSAccessibilityPlaceholderValueAttribute)
            if placeholder and target_text in placeholder:
                return element
        except:
            pass

        try:
            children = element.accessibilityAttributeValue_(NSAccessibilityChildrenAttribute)
            if children:
                for child in children:
                    result = search_recursive(child, target_text)
                    if result:
                        return result
        except:
            pass

        return None

    return search_recursive(window, placeholder_text)

# Find the search field
print("Looking for search field...")
search_field = find_element_by_placeholder("Search")

if search_field:
    print("Found search field!")
    try:
        # Try to set focus to the search field
        search_field.accessibilitySetValue_forAttribute_(True, NSAccessibilityFocusedAttribute)
        time.sleep(0.2)

        # Try to type in the field
        search_field.accessibilitySetValue_forAttribute_("Book", NSAccessibilityValueAttribute)
        print("Set value to 'Book'")

        time.sleep(0.5)
    except Exception as e:
        print(f"Error: {e}")
else:
    print("Search field not found")

# Take screenshot
import subprocess
print("\nTaking screenshot...")
subprocess.run(["xcrun", "simctl", "io", "20D22F10-CAF1-43F7-BFB2-3A749EEB873E", "screenshot", "/tmp/screen_accessibility.png"],
               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
print("Done!")
EOF

